namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetFeaturedCourses();
    bool SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, patterns, and quantitative reasoning." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Understanding the fundamental laws governing matter and energy." },
            new() { Id = 4, Code = "ENGL", Name = "English", Description = "Analysis of literature, language, and written communication." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, cultures, and civilizations." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, and an overview of key areas in the field.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Location = "Science Hall 110", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a Ph.D. from MIT and specializes in programming languages and CS education.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures such as lists, trees, and graphs, along with algorithm design and analysis techniques.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", Location = "Science Hall 215", InstructorName = "Dr. Brian Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization and competitive programming pedagogy.", IsFeatured = false },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 301", Title = "Operating Systems", Description = "Core concepts of operating system design including process management, memory allocation, file systems, and concurrency.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", Location = "Science Hall 310", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a Ph.D. from MIT and specializes in programming languages and CS education.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, CourseCode = "CS 350", Title = "Machine Learning Fundamentals", Description = "Introduction to supervised and unsupervised learning, neural networks, and practical applications of machine learning.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", Location = "Science Hall 405", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma is an AI researcher with publications in top-tier ML conferences.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to science and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", Location = "Math Building 102", InstructorName = "Dr. Robert Hayes", InstructorBio = "Dr. Hayes has taught calculus for over 20 years and has authored two widely used textbooks.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", Location = "Math Building 204", InstructorName = "Dr. Susan Lee", InstructorBio = "Dr. Lee specializes in applied mathematics and has consulted for several engineering firms.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, CourseCode = "MATH 310", Title = "Probability and Statistics", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", Location = "Math Building 108", InstructorName = "Dr. Robert Hayes", InstructorBio = "Dr. Hayes has taught calculus for over 20 years and has authored two widely used textbooks.", IsFeatured = false },

            // Physics
            new() { Id = 8, DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes a weekly laboratory component.", Credits = 4, Schedule = "MWF 10:00–10:50 AM", Location = "Physics Lab 101", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor is an experimental physicist with expertise in classical mechanics and optics.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, CourseCode = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, and introductory modern physics. Laboratory included.", Credits = 4, Schedule = "TTh 1:00–2:20 PM", Location = "Physics Lab 101", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor is an experimental physicist with expertise in classical mechanics and optics.", IsFeatured = false },
            new() { Id = 10, DepartmentId = 3, CourseCode = "PHYS 320", Title = "Quantum Mechanics", Description = "Introduction to quantum theory, wave functions, the Schrödinger equation, and applications to atomic systems.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", Location = "Physics Lab 210", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez is a theoretical physicist whose work focuses on quantum computing foundations.", IsFeatured = true },

            // English
            new() { Id = 11, DepartmentId = 4, CourseCode = "ENGL 101", Title = "English Composition", Description = "Development of college-level writing skills including argument construction, research methods, and rhetorical analysis.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Location = "Humanities 205", InstructorName = "Prof. Linda Crawford", InstructorBio = "Prof. Crawford is an award-winning writing instructor and published essayist.", IsFeatured = false },
            new() { Id = 12, DepartmentId = 4, CourseCode = "ENGL 220", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", Location = "Humanities 310", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a literary scholar specializing in 20th-century American fiction.", IsFeatured = false },
            new() { Id = 13, DepartmentId = 4, CourseCode = "ENGL 340", Title = "Creative Writing Workshop", Description = "A workshop-based course focused on fiction and poetry writing, peer critique, and revision techniques.", Credits = 3, Schedule = "W 3:00–5:50 PM", Location = "Humanities 112", InstructorName = "Prof. Linda Crawford", InstructorBio = "Prof. Crawford is an award-winning writing instructor and published essayist.", IsFeatured = false },

            // History
            new() { Id = 14, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "A survey of world civilizations from antiquity through the late medieval period.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", Location = "Liberal Arts 150", InstructorName = "Dr. Karen Mitchell", InstructorBio = "Dr. Mitchell is a medievalist who has published extensively on cross-cultural exchanges in the ancient world.", IsFeatured = false },
            new() { Id = 15, DepartmentId = 5, CourseCode = "HIST 201", Title = "Modern European History", Description = "European history from the Enlightenment through the 21st century, including revolutions, world wars, and the European Union.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", Location = "Liberal Arts 220", InstructorName = "Dr. Thomas Weber", InstructorBio = "Dr. Weber is a historian of modern Europe with a focus on Franco-German relations.", IsFeatured = true },
            new() { Id = 16, DepartmentId = 5, CourseCode = "HIST 310", Title = "The American Civil War", Description = "In-depth study of the causes, conduct, and consequences of the American Civil War.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", Location = "Liberal Arts 150", InstructorName = "Dr. Karen Mitchell", InstructorBio = "Dr. Mitchell is a medievalist who has published extensively on cross-cultural exchanges in the ancient world.", IsFeatured = false }
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments.AsReadOnly();

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList().AsReadOnly();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public bool SubmitEnrollment(EnrollmentRequest request) => true;
}

