@page "/courses"
@rendermode InteractiveServer
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-3">Course Catalog</h1>

<div class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" class="form-control" placeholder="Search by title or course code…" @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary w-100" @onclick="ApplyFilters">Search</button>
    </div>
</div>

@if (FilteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Course Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in FilteredCourses)
                {
                    var dept = CatalogService.GetDepartment(course.DepartmentId);
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@(dept?.Name ?? "—")</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private string SearchTerm { get; set; } = string.Empty;
    private int SelectedDepartmentId { get; set; }
    private IReadOnlyList<Course> FilteredCourses { get; set; } = [];

    protected override void OnInitialized()
    {
        if (DepartmentId.HasValue)
            SelectedDepartmentId = DepartmentId.Value;

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = SelectedDepartmentId > 0 ? SelectedDepartmentId : null;
        var term = string.IsNullOrWhiteSpace(SearchTerm) ? null : SearchTerm;
        FilteredCourses = CatalogService.GetCourses(term, deptFilter);
    }
}

@page "/courses/{Id:int}"
@inject ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Detail")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="courses" class="btn btn-secondary">Back to Courses</a>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.Title</h1>
    <p>
        <span class="badge bg-primary me-1">@course.CourseCode</span>
        <span class="badge bg-secondary me-1">@course.Credits Credits</span>
        @if (dept is not null)
        {
            <span class="badge bg-info text-dark">@dept.Name</span>
        }
    </p>

    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Description</h5>
            <p class="card-text">@course.Description</p>
        </div>
    </div>

    <div class="row mb-4">
        <div class="col-md-6">
            <h5>Schedule &amp; Location</h5>
            <ul class="list-unstyled">
